 if(mL==="industry")INDU().forEach(c=>{const [x,y]=PX(c[1],c[2]),on=mSel===c[0],o=c[7],col=css(c[4]);g+=`<g class="pin" data-in="${c[0]}" tabindex="0" role="button" aria-label="${c[3]}"><rect x="${x-(on?13:10)}" y="${y-(on?13:10)}" width="${on?26:20}" height="${on?26:20}" rx="6" fill="${on?col:"#fff"}" stroke="${col}" stroke-width="3"/><text x="${x+o[0]}" y="${y+o[1]+(o[2]==="middle"?0:5)}" text-anchor="${o[2]}" font-size="${on?19:16}" font-weight="600" fill="${css('--ink')}" ${halo(6)}>${c[3]}</text></g>`});
