pSvg.addEventListener("pointermove",e=>{if(!dragH)return;const q=svgP(e);let deg=Math.atan2(q.y-PC,q.x-PC)*180/Math.PI+90;if(deg<0)deg+=360;let p=Math.round(deg/3.6);
 const cum=[0];plate.forEach(v=>cum.push(cum[cum.length-1]+v));const lo=cum[dragH-1],hi=cum[dragH+1];
 ptip.style.opacity=0;if(p<lo-30)p+=100;p=Math.max(lo,Math.min(hi,p));plate[dragH-1]=p-lo;plate[dragH]=hi-p;selCat=dragH-1;edited=true;gameUpdate()});
pSvg.addEventListener("pointerup",()=>{dragH=0;drawPlate();focusUI()});
pSvg.addEventListener("keydown",e=>{const h=e.target.closest(".hd");if(!h)return;const i=+h.dataset.h;const d=e.key==="ArrowRight"||e.key==="ArrowUp"?1:e.key==="ArrowLeft"||e.key==="ArrowDown"?-1:0;if(!d)return;e.preventDefault();
 if(d>0&&plate[i]>0){plate[i]--;plate[i-1]++}else if(d<0&&plate[i-1]>0){plate[i-1]--;plate[i]++}gameUpdate();pSvg.querySelector(`.hd[data-h="${i}"]`)?.focus()});
const nudge=(i,d)=>{const step=5*d;const others=plate.map((v,j)=>j).filter(j=>j!==i);let need=step;
 if(d>0){need=Math.min(step,100-plate[i]);let pool=others.reduce((s,j)=>s+plate[j],0);if(!pool)return;let taken=0;others.forEach(j=>{const t=Math.round(need*plate[j]/pool);plate[j]-=t;taken+=t});plate[i]+=taken}
 else{const give=Math.min(-step,plate[i]);plate[i]-=give;const per=Math.floor(give/others.length);others.forEach(j=>plate[j]+=per);plate[others[0]]+=give-per*others.length}
 edited=true;plate=plate.map(v=>Math.max(0,v));const diff=100-plate.reduce((s,v)=>s+v,0);const big=plate.indexOf(Math.max(...plate));plate[big]+=diff;selCat=i;selLv=cats()[i].lv;gameUpdate()};
const badgeOf=s=>s>=90?tx(ref==="swiss"?"Pyramid pro":"Planet pro",ref==="swiss"?"Pro de la pyramide":"Pro de la planète"):s>=75?tx("Alpine balance","Équilibre alpin"):s>=55?tx("Getting there","En bonne voie"):tx("Raclette night","Soirée raclette");
let lastBadge="";
const gamePanel=()=>{const C_=cats(),R_=REF[ref],s=sc(ref);
 document.getElementById("gScoreN").textContent=s;const b=document.getElementById("badge"),bt=badgeOf(s);b.textContent=bt;if(bt!==lastBadge&&lastBadge){b.classList.add("pop");setTimeout(()=>b.classList.remove("pop"),300)}lastBadge=bt;
 document.getElementById("catRows").innerHTML=`<div class="small mute" style="margin-bottom:4px">${tx(`Compared with the ${ref==="swiss"?"Swiss food pyramid":"planet-friendly plate"}. Average Swiss man: ${scOf(REF.avg,ref)}/100.`,`Comparé à ${ref==="swiss"?"la pyramide alimentaire suisse":"l'assiette planétaire"}. Homme suisse moyen : ${scOf(REF.avg,ref)}/100.`)}</div>`+C_.map((c,i)=>{const d=plate[i]-R_[i];
  const hint=Math.abs(d)<=4?tx("✓ about right","✓ c'est bien"):d>0?tx(`${d} points too much`,`${d} points de trop`):tx(`${-d} points more`,`${-d} points de plus`);
  return `<div class="crow${i===selCat?" on":""}" data-i="${i}" style="--c:var(${c.c})"><i></i><span>${c.n}<span class="h">${hint}</span></span><span class="v"><b>${plate[i]}%</b> <span class="mute">/ ${R_[i]}%</span></span><button class="pm" data-i="${i}" data-d="-1" aria-label="${tx("Less","Moins")} ${c.n}">−</button><button class="pm" data-i="${i}" data-d="1" aria-label="${tx("More","Plus")} ${c.n}">+</button></div>`}).join("");
 document.querySelectorAll("#catRows .pm").forEach(x=>x.onclick=e=>{e.stopPropagation();nudge(+x.dataset.i,+x.dataset.d)});
 document.querySelectorAll("#catRows .crow").forEach(x=>{x.onclick=()=>{selCat=+x.dataset.i;selLv=C_[selCat].lv;gamePanel()};x.onmouseenter=()=>setHov([+x.dataset.i]);x.onmouseleave=()=>setHov(null)});
 CH().forEach((c,i)=>{if(c.ok())done.add(i)});
 document.getElementById("chal").innerHTML=CH().map((c,i)=>`<li class="${done.has(i)?"done":""}"><b>${done.has(i)?"✓":""}</b><span>${c.t}</span></li>`).join("")+``;document.getElementById("chalN").textContent=`${done.size}/${CH().length}`;
 focusUI();profile();summary();document.getElementById("avgNote").textContent=ring!=="avg"?ringNote():tx("Coloured ring = an average Swiss man's day (menuCH 2014–15): fewer vegetables, more grains and meat, almost no legumes. Only 18% of adults eat 5 fruit and veg a day.","Anneau coloré = la journée d'un homme suisse moyen (menuCH 2014–15) : moins de légumes, plus de céréales et de viande, presque pas de légumineuses. Seuls 18 % des adultes mangent 5 fruits et légumes par jour.");};
const drawPyr=()=>{const L_=lvls(),s=document.getElementById("pyr"),C_=cats(),F=focusOf();const H=230/7;let g="";
 const hotL=pyrHov!=null?[pyrHov]:F?F.map(i=>C_[i].lv):null,cur=pyrHov??(F?C_[F[0]].lv:selLv);
 L_.forEach((l,i)=>{const yb=240-i*H,yt=yb-H,hw=y=>88*(y-10)/230,on=hotL&&hotL.includes(i);g+=`<g class="lv" data-l="${i}" tabindex="0" role="button" aria-label="${l[0]}" opacity="${hotL&&!on?.35:1}" style="transition:opacity .2s"><path d="M${95-hw(yb)},${yb}L${95+hw(yb)},${yb}L${95+hw(yt)},${yt}L${95-hw(yt)},${yt}Z" fill="${l[1]}" stroke="${i===cur?css('--ink'):"#fff"}" stroke-width="${i===cur?2.5:2}"/>
 <line x1="${95+hw(yb-H/2)+4}" y1="${yb-H/2}" x2="196" y2="${yb-H/2}" stroke="${css('--line')}"/><text x="200" y="${yb-H/2+5}" font-size="14" font-weight="${i===cur?600:400}" fill="${css('--ink')}">${l[0]}</text></g>`});
 s.innerHTML=g;s.querySelectorAll(".lv").forEach(x=>{const f=()=>{selLv=+x.dataset.l;pyrHov=null;drawPyr()};x.onclick=f;x.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();f()}}});
 const cs=C_.map((c,i)=>c.lv===cur?i:-1).filter(i=>i>=0);
 document.getElementById("pyrTip").innerHTML=`<b>${L_[cur][0]}</b>${cs.length?` · <span class="mute">${tx("your plate","votre assiette")}: ${cs.map(i=>`<b style="color:var(${C_[i].c})">${plate[i]}%</b>`).join(" + ")}</span>`:""}<br>${L_[cur][2]}`};
{const s=document.getElementById("pyr");s.addEventListener("pointermove",e=>{const t=e.target.closest(".lv");const l=t?+t.dataset.l:null;if(l===pyrHov)return;pyrHov=l;const C_=cats(),cs=l==null?null:C_.map((c,i)=>c.lv===l?i:-1).filter(i=>i>=0);hov=cs&&cs.length?cs:null;drawPlate();focusUI()});
 s.addEventListener("pointerleave",()=>{pyrHov=null;hov=null;drawPlate();focusUI()})}
