 w.innerHTML=g;w.querySelectorAll(".ms").forEach(x=>{const f=()=>{cm=+x.dataset.m;cal()};x.onclick=f;x.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();f()}}});
