const miniTT=k=>{const d=YR[k],mx=Math.max(...d.map(x=>Math.max(x[5],x[6])),1);const P=(j,c)=>d.map((x,i)=>(i?"L":"M")+(i/62*260).toFixed(1)+","+(70-x[j]/mx*64).toFixed(1)).join("");return `<svg viewBox="0 0 260 74" class="mini" aria-hidden="true"><path d="${P(5)}" fill="none" stroke="${css('--red')}" stroke-width="2.5"/><path d="${P(6)}" fill="none" stroke="${css('--blue')}" stroke-width="2.5"/></svg><div class="legend"><span style="--c:var(--red)">${tx("Meat","Viande")}</span><span style="--c:var(--blue)">${tx("Fish","Poisson")}</span><span style="--c:transparent">1961 → 2023</span></div>`};
