let covI=0,covCur=null,covT=null,covA=null;
const covS=()=>[[CP.CHE.plate1961,"1961",tx("The Swiss plate","L'assiette suisse")],[CP.CHE.plate,"2023",tx("The Swiss plate today","L'assiette suisse aujourd'hui")],[REF.phd,tx("Tomorrow?","Demain ?"),tx("A flexitarian plate","Une assiette flexitarienne")]];
const covDraw=pl=>{const s=document.getElementById("covPlate");if(!s)return;const C_=cats();let g=`<circle cx="200" cy="200" r="194" fill="#fff" stroke="${css('--line')}" stroke-width="2"/><circle cx="200" cy="200" r="170" fill="#fafbf9" stroke="${css('--line')}"/>`,a=0;
 pl.forEach((v,i)=>{if(v>.3)g+=`<path d="${arc(a,a+v,0,158)}" fill="${css(C_[i].c)}" stroke="#fff" stroke-width="3"/>`;if(v>=7){const [x,y]=pt(a+v/2,110);g+=`<text x="${x}" y="${y+7}" text-anchor="middle" font-size="20" font-weight="600" fill="#fff">${Math.round(v)}%</text>`}a+=v});
 s.innerHTML=g+`<circle cx="200" cy="200" r="42" fill="#fff"/>`};
const covGo=()=>{const S_=covS(),st=S_[covI],from=covCur||st[0],to=st[0],t0=performance.now(),D=reduce?0:1300;
 document.getElementById("covYear").textContent=st[1];document.getElementById("covLab").textContent=st[2];
 document.querySelectorAll("#covDots button").forEach((d,j)=>d.setAttribute("aria-pressed",j===covI));
 cancelAnimationFrame(covA);const step=n=>{const p=D?Math.min(1,(n-t0)/D):1,e=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;covCur=from.map((v,i)=>v+(to[i]-v)*e);covDraw(covCur);if(p<1)covA=requestAnimationFrame(step)};covA=requestAnimationFrame(step)};
const cover=()=>{const d=document.getElementById("covDots");if(!d)return;d.innerHTML=covS().map((s,i)=>`<button aria-label="${s[1]}" aria-pressed="${i===covI}">${s[1]}</button>`).join("");
 d.querySelectorAll("button").forEach((b,i)=>b.onclick=()=>{covI=i;clearInterval(covT);covT=null;covGo()});
 document.getElementById("covLeg").innerHTML=cats().map(c=>`<span class="sq" style="--c:var(${c.c})">${c.n}</span>`).join("");
 if(!covT&&!reduce)covT=setInterval(()=>{covI=(covI+1)%3;covGo()},4200);covGo()};

