{const T=document.createElement("div");T.className="ftip";T.setAttribute("role","tooltip");T.hidden=true;document.body.appendChild(T);let cur=null;
 const show=(el,x,y)=>{cur=el;T.innerHTML=el.dataset.tip;T.hidden=false;const r=T.getBoundingClientRect(),W=innerWidth;let l=x+14,t=y+14;if(l+r.width>W-8)l=x-r.width-14;if(l<8)l=8;if(t+r.height>innerHeight-8)t=y-r.height-14;T.style.left=l+"px";T.style.top=t+"px"};
 const hide=()=>{cur=null;T.hidden=true};
 document.addEventListener("pointermove",e=>{const el=e.target.closest&&e.target.closest("[data-tip]");if(el&&el.dataset.tip&&e.pointerType==="mouse")show(el,e.clientX,e.clientY);else if(cur&&e.pointerType==="mouse")hide()});
 document.addEventListener("click",e=>{const el=e.target.closest&&e.target.closest("[data-tip]");if(el&&el.dataset.tip&&(e.pointerType!=="mouse")){if(cur===el){hide();return}const r=el.getBoundingClientRect();show(el,r.left+r.width/2,r.bottom)}else if(!el)hide()});
 document.addEventListener("focusin",e=>{const el=e.target.closest&&e.target.closest("[data-tip]");if(el&&el.dataset.tip){const r=el.getBoundingClientRect();show(el,r.left+20,r.bottom-6)}});
 document.addEventListener("focusout",hide);addEventListener("scroll",()=>{if(cur)hide()},{passive:true})}
